/// Renders `<ac:link>` (page, attachment, or URL) as Markdown.
String _linkToMarkdown(_XmlNode node) {
  final body = node.child('ac:link-body')?.content ?? '';
  final page = node.child('ri:page')?.attrs['ri:content-title'];
