String _taskToMarkdown(_XmlNode node) {
  final status = node.child('ac:task-status')?.content ?? 'incomplete';
  final body = node.child('ac:task-body')?.content ?? '';
  return '- [${status == 'complete' ? 'x' : ' '}] $body\n';
