/// `url` parameter (when present) is kept.
String _whiteboardMarker(_XmlNode node) {
  for (final param in node.children) {
    if (param.name == 'ac:parameter' && param.attrs['ac:name'] == 'url') {
      final url = param.content.trim();
      if (url.isNotEmpty) {
